import * as http from 'node:http';
async function main(): Promise<void> {
  const srv = http.createServer((req, res) => { res.setHeader('content-type', 'text/event-stream'); res.end('ok'); });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const port = (srv.address() as any).port;
  const bad = await fetch('http://127.0.0.1:1/').catch((e: any) => 'failed');
  console.log(bad);
  const good: any = await fetch('http://127.0.0.1:' + port + '/').catch(() => null);
  const isSse = good.headers.get('content-type')?.includes('text/event-stream');
  const none = good.headers.get('x-none')?.includes('x');
  console.log(isSse, none, typeof isSse);
  srv.close();
}
